// setHTMLElemStyle puzzle
function setHTMLElemStyle(prop, value, ids, isParent) {
    var elems = PzLib.getElements(ids, isParent);
    for (var i = 0; i < elems.length; i++) {
        var elem = elems[i];
        if (!elem || !elem.style)
            continue;
        elem.style[prop] = value;
    }
}

// getUrlData puzzle
function getUrlData(kind, isParent) {

    var targetWindow = isParent ? window.parent : window;
    switch (kind) {
    case 'URL':
        return targetWindow.location.href;
    case 'PAGE_NAME':
        return targetWindow.location.pathname.split("/").slice(-1)[0];
    case 'PARAMS':
        return v3d.AppUtils.getPageParams(targetWindow);
    case 'HOSTNAME':
        return targetWindow.location.hostname;
    default:
        console.error('get URL data puzzle: option does not exists.');
        return '';
    }

}

// dictGet puzzle
function dictGet(dict, key, defaultValue) {
    if (dict && typeof dict == 'object')
        return (key in dict) ? dict[key] : defaultValue;
}

// setTimeout puzzle
