// sendData puzzle
async function sendData(data, url, headers, onceReadyCb, onErrorCb) {
    try {
        const options = {
            method: 'POST',
            headers: {}
        }

        if (typeof data == 'string') {
            options.headers['Content-Type'] = 'text/plain';
            options.body = data;
        } else if (data instanceof FormData) {
            // no Content-Type here
            options.body = data;
        } else {
            // serialize to json
            options.headers['Content-Type'] = 'application/json';
            options.body = JSON.stringify(data);
        }

        Object.assign(options.headers, headers);

        const response = await fetch(url, options);
        if (!response.ok)
            throw new Error('Network error with status ' + response.status);

        if (response.headers.get('Content-Type').startsWith('application/json'))
            _pGlob.loadedFile = await response.json();
        else
            _pGlob.loadedFile = await response.text();

        onceReadyCb();

    } catch (error) {

        console.error('send data puzzle:', error.message);
        _pGlob.loadedFile = '';
        onErrorCb();

    }
}

